#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;
using i64 = long long;

constexpr int MOD = 998244353;
constexpr int MOD2 = 1000000007;

struct FastReader {
    static constexpr size_t BUF = 1 << 21;
    char buf[BUF], *p = buf, *end = buf;

    int getc() {
        if (p == end) {
            end = buf + fread(buf, 1, BUF, stdin);
            p = buf;
        }
        return (p == end) ? EOF : *p++;
    }

    template<typename T>
    T read() {
        char c;
        while ((c = getc()) < '0' || c > '9') {
            if (c == EOF) return -1;
            if (c == '-') {
                T x = 0;
                while ((c = getc()) >= '0' && c <= '9') x = x * 10 + (c - '0');
                return -x;
            }
        }
        T x = c - '0';
        while ((c = getc()) >= '0' && c <= '9') x = x * 10 + (c - '0');
        return x;
    }
};

struct FastWriter {
    static constexpr size_t BUF = 1 << 21;
    char buf[BUF], *p = buf;

    ~FastWriter() { flush(); }

    void flush() {
        fwrite(buf, 1, p - buf, stdout);
        p = buf;
    }

    void putc(char c) {
        *p++ = c;
        if (p - buf >= BUF) flush();
    }

    template<typename T>
    void write(T x, char sep = '\n') {
        if (x < 0) { putc('-'); x = -x; }
        if (x == 0) { putc('0'); if (sep != -1) putc(sep); return; }
        char tmp[20];
        int len = 0;
        while (x) { tmp[len++] = '0' + x % 10; x /= 10; }
        while (len--) putc(tmp[len]);
        if (sep != -1) putc(sep);
    }

    void write(const char* s) {
        while (*s) putc(*s++);
    }
};

constexpr i64 powers[8] = {1, 10, 100, 1000, 10000, 100000, 1000000, 10000000};

int global_counter = 0;
int final_answer = 0;
i64 N;
i64 sums[7];
int counts[7];
vector<int> data[7];

void build_data(int cur, int depth) {
    int val = (global_counter - cur + MOD) % MOD;
    data[depth].push_back(val);
    sums[depth] = (sums[depth] + val) % MOD;
    counts[depth]++;
    global_counter++;

    if (depth == 6) return;
    for (int d = 0; d < 10; ++d) {
        build_data(cur * 10 + d, depth + 1);
    }
}

void solve_query(int base, i64 pos) {
    for (int d = 0; d < 7; ++d) {
        i64 target = (pos - 1LL * base * powers[d]) % MOD;
        if (target < 0) target += MOD;

        auto it = lower_bound(data[d].begin(), data[d].end(), MOD - target);
        int cnt = data[d].end() - it;

        int part1 = sums[d];
        int part2 = (1LL * target * counts[d]) % MOD;
        int part3 = (1LL * cnt * MOD) % MOD;

        final_answer = (final_answer + part1 + part2 - part3) % MOD2;
        if (final_answer < 0) final_answer += MOD2;
    }
}

void dfs(i64 cur) {
    if ((cur + 1) * powers[6] <= N + 1 && cur * powers[7] > N) {
        solve_query(cur, global_counter + 1);
        global_counter += global_counter;
        return;
    }

    global_counter++;
    int diff = ((global_counter - cur) % MOD + MOD) % MOD;
    final_answer = (final_answer + diff) % MOD2;

    for (int d = (cur == 0 ? 1 : 0); d < 10; ++d) {
        i64 next_val = cur * 10 + d;
        if (next_val <= N) {
            dfs(next_val);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    FastReader reader;
    FastWriter writer;

    build_data(0, 0);
    N = reader.read<i64>();
    dfs(0);
    writer.write(final_answer);

    return 0;
}
